testsCode:
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { linhaDeLog, nivelDoStatus } from './solution.mjs';

test('linhaDeLog devolve um JSON com os campos fixos', () => {
  const linha = linhaDeLog('info', 'servidor subiu');
  assert.deepEqual(JSON.parse(linha), {
    level: 'info',
    msg: 'servidor subiu',
    timestamp: '2026-08-27T12:00:00.000Z'
  });
});

test('linhaDeLog inclui os extras espalhados no JSON', () => {
  const linha = linhaDeLog('error', 'deu ruim', { rota: '/pedidos', status: 500 }, '2026-08-27T12:00:00.000Z');
  assert.deepEqual(JSON.parse(linha), {
    level: 'error',
    msg: 'deu ruim',
    timestamp: '2026-08-27T12:00:00.000Z',
    rota: '/pedidos',
    status: 500
  });
});

test('nivelDoStatus classifica 5xx como error', () => {
  assert.equal(nivelDoStatus(500), 'error');
  assert.equal(nivelDoStatus(503), 'error');
});

test('nivelDoStatus classifica 4xx como warn e o resto como info', () => {
  assert.equal(nivelDoStatus(404), 'warn');
  assert.equal(nivelDoStatus(400), 'warn');
  assert.equal(nivelDoStatus(200), 'info');
  assert.equal(nivelDoStatus(301), 'info');
});

solutionCode:
export function linhaDeLog(level, msg, extras = {}, timestamp = '2026-08-27T12:00:00.000Z') {
  return JSON.stringify({ level, msg, timestamp, ...extras });
}

export function nivelDoStatus(status) {
  if (status >= 500) return 'error'; // o servidor quebrou
  if (status >= 400) return 'warn';  // quem errou foi quem chamou
  return 'info';
}
